export function MarkdownEditor({
  markdownText = "{{markdownText}}",
  accent = "{{accent}}",
  showLineNumbers = {{showLineNumbers}},
  toolbarStyle = "{{toolbarStyle}}",
  fontSize = {{fontSize}},
}) {
  const expanded = toolbarStyle === "expanded";
  const btn = { height: 26, padding: "0 6px", border: "none", background: "transparent", borderRadius: 6, cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 6 };
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: "#241430", background: "#FAF7F2", border: "1.5px solid #24143020", borderRadius: 10, overflow: "hidden", maxWidth: 420, fontSize }}>
      <div role="toolbar" aria-label="Markdown formatting" style={{ display: "flex", gap: 2, padding: 6, background: "#24143008", borderBottom: "1.5px solid #24143020" }}>
        <button type="button" aria-label="Heading" style={btn}>H{expanded && <span style={{ fontSize: 12 }}>Heading</span>}</button>
        <button type="button" aria-label="Bold" style={btn}><strong>B</strong>{expanded && <span style={{ fontSize: 12 }}>Bold</span>}</button>
        <button type="button" aria-label="Italic" style={btn}><em>I</em>{expanded && <span style={{ fontSize: 12 }}>Italic</span>}</button>
        <button type="button" aria-label="Link" style={btn}>{"\u{1F517}"}{expanded && <span style={{ fontSize: 12 }}>Link</span>}</button>
      </div>
      <div style={{ display: "flex" }}>
        {showLineNumbers && (
          <div aria-hidden="true" style={{ display: "flex", flexDirection: "column", gap: 2, padding: "12px 8px", color: "#24143066", fontFamily: "ui-monospace, monospace", fontSize: "0.9em", borderRight: "1px solid #24143014" }}>
            <span>1</span><span>2</span><span>3</span>
          </div>
        )}
        <div contentEditable suppressContentEditableWarning role="textbox" aria-multiline="true" aria-label="Markdown source"
          style={{ flex: 1, padding: "12px 14px", fontFamily: "ui-monospace, SFMono-Regular, monospace", whiteSpace: "pre-wrap", minHeight: "3.2em" }}>
          {markdownText}
        </div>
      </div>
    </div>
  );
}
